import{_ as d,o as r,c as e,ae as o}from"./chunks/framework.BajMXG5H.js";const u=JSON.parse('{"title":"リアルタイム監視","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/real-time-monitoring.md","filePath":"ja/guide/real-time-monitoring.md"}'),a={name:"ja/guide/real-time-monitoring.md"};function n(s,t,i,l,h,g){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="リアルタイム監視" tabindex="-1">リアルタイム監視 <a class="header-anchor" href="#リアルタイム監視" aria-label="Permalink to &quot;リアルタイム監視&quot;">​</a></h1><p>Orchestraは全てのClaude Codeセッションをライブステータス更新で単一のダッシュボードから監視します。</p><h2 id="仕組み" tabindex="-1">仕組み <a class="header-anchor" href="#仕組み" aria-label="Permalink to &quot;仕組み&quot;">​</a></h2><p>Claude Code実行時、重要なタイミングでhookイベントが発火されます（ツール使用、完了、エラー、サブエージェントのアクティビティ）。OrchestraはこれらのイベントをHTTPで受信し、ダッシュボードをリアルタイムで更新します。</p><h2 id="セッションの状態" tabindex="-1">セッションの状態 <a class="header-anchor" href="#セッションの状態" aria-label="Permalink to &quot;セッションの状態&quot;">​</a></h2><p>各セッションカードは現在の状態を表示します:</p><table tabindex="0"><thead><tr><th>ステータス</th><th>意味</th></tr></thead><tbody><tr><td><strong>Running</strong></td><td>Claudeがアクティブに作業中</td></tr><tr><td><strong>Waiting Input</strong></td><td>Claudeが停止しユーザーの入力を待機中</td></tr><tr><td><strong>Waiting Permission</strong></td><td>続行するために権限が必要</td></tr><tr><td><strong>Error</strong></td><td>エラーが発生</td></tr><tr><td><strong>Done</strong></td><td>セッションが終了</td></tr></tbody></table><h2 id="アクティビティタイプ" tabindex="-1">アクティビティタイプ <a class="header-anchor" href="#アクティビティタイプ" aria-label="Permalink to &quot;アクティビティタイプ&quot;">​</a></h2><p>Claudeが現在何をしているかをアニメーション付きアイコンで表示します:</p><table tabindex="0"><thead><tr><th>アクティビティ</th><th>説明</th><th>ツール</th></tr></thead><tbody><tr><td><strong>Thinking</strong></td><td>ツール呼び出し間のLLM推論</td><td>—</td></tr><tr><td><strong>Research</strong></td><td>検索・調査</td><td>Grep, Glob, WebSearch</td></tr><tr><td><strong>Reading</strong></td><td>ファイル読み取り</td><td>Read</td></tr><tr><td><strong>Writing</strong></td><td>ファイルの編集・作成</td><td>Edit, Write</td></tr><tr><td><strong>Coding</strong></td><td>コード編集ツール</td><td>Edit, Write（コードコンテキスト）</td></tr><tr><td><strong>Running</strong></td><td>コマンド実行</td><td>Bash</td></tr><tr><td><strong>Testing</strong></td><td>テスト実行</td><td>Bash（テストコマンド）</td></tr><tr><td><strong>Tooling</strong></td><td>外部ツール呼び出し</td><td>MCPツール</td></tr><tr><td><strong>Compacting</strong></td><td>コンテキストウィンドウの圧縮</td><td>PreCompactイベント</td></tr><tr><td><strong>Delegating</strong></td><td>サブエージェント管理</td><td>アクティブなサブエージェント実行中</td></tr><tr><td><strong>Idle</strong></td><td>アクティブなツール使用なし</td><td>—</td></tr></tbody></table><h2 id="表示モード" tabindex="-1">表示モード <a class="header-anchor" href="#表示モード" aria-label="Permalink to &quot;表示モード&quot;">​</a></h2><p>セッションの表示に2つのレイアウトを選択できます:</p><ul><li><strong>グリッド表示</strong> (<code>⌘1</code>) — セッション情報を詳細に表示するカードベースのレイアウト</li><li><strong>リスト表示</strong> (<code>⌘2</code>) — 素早く確認できるコンパクトな行ベースのレイアウト</li></ul><h3 id="検索・フィルター" tabindex="-1">検索・フィルター <a class="header-anchor" href="#検索・フィルター" aria-label="Permalink to &quot;検索・フィルター&quot;">​</a></h3><p>検索バー (<code>⌘F</code>) でセッションをタイトルでフィルターできます。tmuxセッションが検出されると、上部にタブが表示され、tmuxセッション単位でのフィルターが可能です。</p><h3 id="表示オプション" tabindex="-1">表示オプション <a class="header-anchor" href="#表示オプション" aria-label="Permalink to &quot;表示オプション&quot;">​</a></h3><p><strong>View</strong>メニューから設定可能:</p><table tabindex="0"><thead><tr><th>オプション</th><th>説明</th><th>デフォルト</th></tr></thead><tbody><tr><td><strong>Group by tmux Session</strong></td><td>tmuxセッション単位でグループ化</td><td>Off</td></tr><tr><td><strong>Show Relative Time</strong></td><td>タイムスタンプの代わりに「2分前」のような相対時間を表示</td><td>On</td></tr></tbody></table><h2 id="セッションカード" tabindex="-1">セッションカード <a class="header-anchor" href="#セッションカード" aria-label="Permalink to &quot;セッションカード&quot;">​</a></h2><p>各セッションカードには以下が表示されます:</p><ul><li><strong>タイトル</strong> — 作業ディレクトリ名から自動取得</li><li><strong>ステータスバッジ</strong> — カラーコード付きの現在のセッション状態</li><li><strong>アクティビティアイコン</strong> — 現在のアクティビティタイプを示すアニメーションアイコン</li><li><strong>エージェントバッジ</strong> — 検出されたAIエージェント（Claude, Codex, Gemini等）の識別子</li><li><strong>最終アクティビティ</strong> — 最新のツールやコマンド出力</li><li><strong>Jumpボタン</strong> — ターミナルセッションへのワンクリックナビゲーション</li><li><strong>サブエージェント数</strong> — アクティブなサブエージェント数（委譲中に表示）</li></ul><p>エージェントバッジの表示/非表示は <strong>Orchestra</strong>メニュー → <strong>Show Agent Badges</strong> から切り替えられます。</p><h2 id="チームモード" tabindex="-1">チームモード <a class="header-anchor" href="#チームモード" aria-label="Permalink to &quot;チームモード&quot;">​</a></h2><p>Claude Codeの<a href="https://docs.anthropic.com/en/docs/claude-code/agent-teams" target="_blank" rel="noreferrer">Agent Teams</a>モードで実行すると、Orchestraは自動的にチームメンバーを検出し、特別な視覚表現で表示します:</p><ul><li><strong>虹色枠</strong> — チームリードのセッションは鮮やかな虹色の回転ボーダー</li><li><strong>ソフト虹色枠</strong> — チームメンバーのセッションはより柔らかい虹色ボーダー</li><li><strong>ロールバッジ</strong> — 各チームセッションカードに「Lead」または「Member」バッジ</li><li><strong>チーム数</strong> — ステータスバーにアクティブなチーム数を表示</li></ul><p>チーム検出は<code>TeammateIdle</code>と<code>TaskCompleted</code>のhookイベント監視と、tmuxウィンドウのグルーピングにより動作します。</p><h2 id="対応hookイベント" tabindex="-1">対応Hookイベント <a class="header-anchor" href="#対応hookイベント" aria-label="Permalink to &quot;対応Hookイベント&quot;">​</a></h2><p>Orchestraは以下のClaude Code hookイベントを処理します:</p><table tabindex="0"><thead><tr><th>イベント</th><th>用途</th></tr></thead><tbody><tr><td>PreToolUse</td><td>ツール使用の開始を追跡</td></tr><tr><td>PostToolUse</td><td>ツール完了を追跡</td></tr><tr><td>Stop</td><td>セッション完了を検出</td></tr><tr><td>Notification</td><td>Claude通知を受信</td></tr><tr><td>SubagentStart</td><td>サブエージェント起動を追跡</td></tr><tr><td>SubagentStop</td><td>サブエージェント完了を追跡</td></tr><tr><td>SessionStart</td><td>セッションの開始/再開を検出</td></tr><tr><td>SessionEnd</td><td>セッション終了を検出</td></tr><tr><td>UserPromptSubmit</td><td>ユーザー入力を追跡</td></tr><tr><td>PermissionRequest</td><td>権限プロンプトを検出</td></tr><tr><td>PreCompact</td><td>コンテキスト圧縮を追跡</td></tr><tr><td>TeammateIdle</td><td>チームメンバーのアイドル検出</td></tr><tr><td>TaskCompleted</td><td>チームタスク完了</td></tr></tbody></table>',29)])])}const m=d(a,[["render",n]]);export{u as __pageData,m as default};
